"""Owner-side execution through the pinned, independently admitted native runtime.

The bridge never invokes response equations directly. An unavailable native
route is an infrastructure HOLD, never a negative scientific observation.
Private scenario inputs and raw sidecars belong outside the investigator sandbox.
"""

from __future__ import annotations

import hashlib
import json
import re
import shlex
import subprocess
import sys
import uuid
from datetime import UTC, datetime
from pathlib import Path

UPSTREAM_COMMIT = "b4823fb4e4babd942e3beafcad8042ea0684f1c0"


class NativeExecutionError(RuntimeError):
    """A native execution/authority error, not scientific evidence."""


def canonical(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def immutable_json(path: Path, value: object) -> str:
    data = canonical(value)
    with path.open("xb") as stream:
        stream.write(data)
    path.chmod(0o600)
    return hashlib.sha256(data).hexdigest()


def load_artifact(root: Path, digest: str) -> dict:
    if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise NativeExecutionError("invalid response digest")
    path = root / f"{digest}.json"
    if path.is_symlink() or path.resolve(strict=True).parent != root.resolve(strict=True):
        raise NativeExecutionError("response must be a local regular artifact")
    data = path.read_bytes()
    if hashlib.sha256(data).hexdigest() != digest:
        raise NativeExecutionError("response digest mismatch")
    result = json.loads(data)
    if not isinstance(result, dict) or result.get("origin") != "synthetic":
        raise NativeExecutionError("native simulator response lost synthetic origin")
    return result


def verify_delivery_binding(delivery: dict, request: dict, world_config: dict, seed: int) -> None:
    """Verify the native seam; detailed measurement validation remains separate."""
    expected_digest = hashlib.sha256(
        canonical({"request": request, "world": world_config, "seed": seed})
    ).hexdigest()
    if delivery.get("provenance", {}).get("request_world_seed_sha256") != expected_digest:
        raise NativeExecutionError("response is not bound to the requested batch and scenario")
    specimens = {specimen["specimen_id"]: specimen for specimen in request["specimens"]}
    delivered = delivery.get("delivered_conditions", {})
    if delivery.get("complete") is not True or set(delivered) != set(specimens):
        raise NativeExecutionError("native delivery specimen membership is incomplete or different")
    default_measurements = (
        ["density_g_cm3"]
        if world_config.get("family") == "rpi_conditional_workflow_v1"
        else ["density_g_cm3", "sps_log"]
    )
    expected = set()
    for sid, specimen in specimens.items():
        identity = {
            "lot_id": request["lot_id"],
            "preparation_id": specimen["preparation_id"],
            "cycle_id": specimen["cycle_id"],
        }
        if any(delivered[sid].get(key) != value for key, value in identity.items()):
            raise NativeExecutionError("native delivery changed specimen genealogy")
        selection = specimen.get(
            "measurements", request.get("measurements", default_measurements)
        )
        expected.update((sid, quantity) for quantity in selection)
    actual = []
    for observation in delivery.get("observations", []):
        sid = observation.get("specimen_id")
        if sid not in specimens or observation.get("origin") != "synthetic":
            raise NativeExecutionError("native observation has a different specimen or origin")
        identity = {
            "lot_id": request["lot_id"],
            "preparation_id": specimens[sid]["preparation_id"],
            "cycle_id": specimens[sid]["cycle_id"],
        }
        if any(observation.get(key) != value for key, value in identity.items()):
            raise NativeExecutionError("native observation changed specimen genealogy")
        actual.append((sid, observation.get("quantity")))
    if len(actual) != len(set(actual)) or set(actual) != expected:
        raise NativeExecutionError("native response differs from the selected measurements")


def verify_trace_replay(source: Path, replay: Path, receipt: dict) -> dict:
    """Check actual replay bytes, not an internal flag omitted by compact CLI receipts.

    Native trace validation is a separate prerequisite. Compare whole observation
    objects, including origin, uncertainty and quality, after reading both files.
    Owner-only traces and their private context hashes are not public fixtures.
    """
    try:
        source_bytes, replay_bytes = source.read_bytes(), replay.read_bytes()
        original = [json.loads(line) for line in source_bytes.splitlines()]
        repeated = [json.loads(line) for line in replay_bytes.splitlines()]
    except (OSError, ValueError) as exc:
        raise NativeExecutionError("native source or replay trace is unreadable") from exc
    source_digest = hashlib.sha256(source_bytes).hexdigest()
    replay_digest = hashlib.sha256(replay_bytes).hexdigest()
    if (
        receipt.get("source_trace_sha256") != source_digest
        or receipt.get("trace_sha256") != replay_digest
    ):
        raise NativeExecutionError("native replay receipt lost exact source or replay binding")
    if not original or len(original) != len(repeated):
        raise NativeExecutionError("native replay changed event membership")
    observation_count = 0
    for before, after in zip(original, repeated, strict=True):
        if (
            after.get("mode") != "replay"
            or after.get("source_trace_sha256") != source_digest
            or before.get("event_type") != after.get("event_type")
            or before.get("sequence") != after.get("sequence")
        ):
            raise NativeExecutionError("native replay changed event ordering or source lineage")
        if before.get("observation") != after.get("observation"):
            raise NativeExecutionError("native replay changed observations or their origins")
        observation_count += before.get("observation") is not None
    if observation_count == 0:
        raise NativeExecutionError("native batch replay contains no observations")
    return {
        "source_trace_sha256": source_digest,
        "replay_trace_sha256": replay_digest,
        "observation_count": observation_count,
        "observations_and_origins_preserved": True,
        "embodied_evidence_bound": False,
    }


class NativeSPSExecutor:
    """Run one complete synthetic batch under native authority with all receipts.

    ``runtime`` is the explicitly prepared isolated source checkout, not a global
    installation or historical HPMS runtime. ``output_root`` is owner-only state.
    Calling twice intentionally creates two native executions; operator-level
    submission/delivery idempotence belongs to the persistent campaign store.
    """

    def __init__(
        self, runtime: str | Path, output_root: str | Path, *, python: str | Path = sys.executable
    ):
        self.runtime = Path(runtime).resolve(strict=True)
        self.root = Path(output_root).resolve()
        # Resolving a venv's interpreter symlink drops its site-packages context.
        interpreter = Path(python).absolute()
        if not interpreter.is_file():
            raise NativeExecutionError("native interpreter is unavailable")
        self.python = str(interpreter)
        self.source_root = Path(__file__).resolve().parents[1]
        self.bundle = self.runtime / "dynamical/bundle/ndfeb-sps"
        if not (self.runtime / ".git").exists():
            raise NativeExecutionError("native runtime must be an explicit pinned checkout")
        revision = subprocess.check_output(
            ["git", "-C", str(self.runtime), "rev-parse", "HEAD"], text=True
        ).strip()
        if revision != UPSTREAM_COMMIT:
            raise NativeExecutionError("native runtime revision mismatch")
        if not (self.bundle / "registry.yaml").is_file():
            raise NativeExecutionError("SPS candidate has not been prepared")
        if Path(output_root).is_symlink():
            raise NativeExecutionError("owner output root may not be a symlink")
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.last_receipt: dict | None = None

    def _command(self, args: list[str], directory: Path, receipt_name: str) -> dict:
        environment = {
            "PATH": "/usr/bin:/bin",
            "LANG": "C.UTF-8",
            "PYTHONNOUSERSITE": "1",
            "PYTHONDONTWRITEBYTECODE": "1",
            "PYTHONPATH": str(self.runtime) + ":" + str(self.source_root),
            "NDFEB_SPS_EXCHANGE_ROOT": str(directory),
        }
        receipt = directory / receipt_name
        program = [self.python, "-m", "dynamical.cli", *args]
        with receipt.open("xb") as stdout, receipt.with_suffix(".stderr").open("xb") as stderr:
            completed = subprocess.run(
                program,
                cwd=directory,
                env=environment,
                stdout=stdout,
                stderr=stderr,
                timeout=120,
                check=False,
            )
        try:
            value = json.loads(receipt.read_bytes())
        except json.JSONDecodeError as exc:
            raise NativeExecutionError(f"unstructured native {args[0]} failure: {receipt}") from exc
        if completed.returncode:
            raise NativeExecutionError(
                f"native {args[0]} HOLD/failed (exit={completed.returncode}): {receipt}"
            )
        return value

    def _follow(self, receipt: dict, verb: str, directory: Path, receipt_name: str) -> dict:
        """Follow the actual native handoff, constrained to this owner invocation."""
        try:
            command = shlex.split(receipt["next_command"])
        except (KeyError, TypeError, ValueError) as exc:
            raise NativeExecutionError("native receipt has no usable next command") from exc
        allowed = {
            "compose": {"--preflight", "--registry", "--facility", "-o"},
            "compile": {"-o"},
            "run": {"--mode", "-o"},
            "validate": {"--json"},
        }
        if len(command) < 3 or command[:2] != ["dynamical", verb] or verb not in allowed:
            raise NativeExecutionError("native handoff changed executable or expected operation")
        root = directory.resolve()
        if not (directory / command[2]).resolve().is_relative_to(root):
            raise NativeExecutionError("native handoff input escaped owner invocation")
        seen = set()
        index = 3
        while index < len(command):
            flag = command[index]
            if flag not in allowed[verb] or flag in seen:
                raise NativeExecutionError("native handoff has an unexpected or repeated option")
            seen.add(flag)
            index += 1
            if flag == "--json":
                continue
            if index >= len(command):
                raise NativeExecutionError("native handoff option lost its value")
            value = command[index]
            index += 1
            if flag == "--mode":
                if value not in {"simulate", "replay"}:
                    raise NativeExecutionError("native handoff requested non-simulator execution")
                continue
            path = (directory / value).resolve()
            if flag in {"--registry", "--facility"}:
                if path != (self.bundle / (flag[2:] + ".yaml")).resolve():
                    raise NativeExecutionError("native handoff changed installed authority inputs")
            elif not path.is_relative_to(root):
                raise NativeExecutionError("native handoff path escaped owner invocation")
            elif flag == "-o" and path.exists():
                raise NativeExecutionError("native handoff would overwrite an existing artifact")
        if (verb != "validate" and "-o" not in seen) or (
            verb == "compose" and "--preflight" not in seen
        ):
            raise NativeExecutionError("native handoff omitted explicit output or preflight")
        return self._command(command[1:], directory, receipt_name)

    @staticmethod
    def _trace_output(receipt: dict, directory: Path) -> Path:
        value = receipt.get("output")
        if not isinstance(value, str):
            raise NativeExecutionError("native receipt omitted trace output")
        path = directory / value
        if path.is_symlink() or not path.resolve().is_relative_to(directory.resolve()):
            raise NativeExecutionError("native trace output escaped owner invocation")
        if not path.is_file():
            raise NativeExecutionError("native trace output is absent")
        return path

    def __call__(
        self, request: dict, *, world_config: dict, seed: int, replay: bool = True
    ) -> dict:
        if request.get("origin") != "synthetic":
            raise NativeExecutionError("physical requests cannot enter a simulator")
        run_id = "native-" + uuid.uuid4().hex
        directory = self.root / run_id
        directory.mkdir(mode=0o700)
        context = {"request": request, "world_config": world_config, "seed": seed}
        context_digest = hashlib.sha256(canonical(context)).hexdigest()
        context_path = directory / f"{context_digest}.json"
        immutable_json(context_path, context)
        requirement = {
            "document_type": "dynamical.campaign-requirement",
            "schema_version": "0.1.0",
            "requirement_id": run_id,
            "objective": {
                "id": "source-grounded-sps-batch",
                "statement": "Execute the proposed SPS batch and selected characterization in a declared synthetic environment.",
                "decision": "Return per-specimen evidence for subsequent investigation; no physical qualification.",
                "proof_requirements": [
                    {
                        "id": "complete-delivery",
                        "operation_id": "process-sps-batch",
                        "output_port_ids": ["response_sha256", "specimen_count"],
                        "minimum_evidence_class": "simulator",
                        "acceptance_rule": "Validate complete delivery digest and preserve individual evidence provenance.",
                        "independent_verification_required": True,
                    }
                ],
            },
            "inputs": [
                {
                    "id": "owner_context_sha256",
                    "state_type": "string",
                    "unit": "1",
                    "value": context_digest,
                    "facility_id": "ndfeb-sps-compute",
                }
            ],
            "steps": [
                {
                    "step_id": "sps-batch",
                    "operation_id": "process-sps-batch",
                    "minimum_evidence_class": "simulator",
                    "parameters": [],
                    "input_bindings": [
                        {
                            "target_port_id": "owner_context_sha256",
                            "source_kind": "campaign_input",
                            "source_id": "owner_context_sha256",
                        }
                    ],
                    "depends_on": [],
                    "required_policy_tags": ["simulation-only"],
                }
            ],
            "max_cost_usd": 0.0,
            "max_duration_s": 60.0,
        }
        immutable_json(directory / "requirement.json", requirement)
        created = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        mapping = {
            "created_at_utc": created,
            "discovery_roots": ["context", "dependencies"],
            "sources": [
                {
                    "ref": "context",
                    "path": str(context_path),
                    "available_at": created,
                    "disposition": "state",
                    "owner": "SPS computational owner",
                },
                {
                    "ref": "dependencies",
                    "path": str(self.bundle / "dependency_lock.json"),
                    "available_at": created,
                    "disposition": "context",
                    "owner": "SPS computational owner",
                },
            ],
            "entities": [
                {
                    "ref": "batch",
                    "kind": "synthetic-batch-context",
                    "source_native_ids": {"sha256": context_digest},
                    "evidence_refs": [{"source_ref": "context"}],
                }
            ],
            "facts": [
                {
                    "ref": "context-digest",
                    "subject_ref": "batch",
                    "field": "owner_context_sha256",
                    "value": context_digest,
                    "kind": "declared",
                    "available_at": created,
                    "state_path": "/sample/owner_context_sha256",
                    "evidence_refs": [{"source_ref": "context"}],
                    "requirement_pointer": "/inputs/0/value",
                }
            ],
            "relations": [],
            "gaps": [],
        }
        immutable_json(directory / "mapping.json", mapping)
        preflight = self._command(
            [
                "preflight",
                "mapping.json",
                "--requirement",
                "requirement.json",
                "--facility",
                str(self.bundle / "facility.yaml"),
                "--registry",
                str(self.bundle / "registry.yaml"),
                "--output",
                "preflight.json",
            ],
            directory,
            "preflight_command.json",
        )
        if preflight.get("status") != "READY":
            raise NativeExecutionError(f"native preflight HOLD: {directory}")
        composed = self._follow(preflight, "compose", directory, "compose_receipt.json")
        compiled = self._follow(composed, "compile", directory, "compile_receipt.json")
        run_receipt = self._follow(compiled, "run", directory, "run_receipt.json")
        validation = self._follow(run_receipt, "validate", directory, "validation_receipt.json")
        trace_path = self._trace_output(run_receipt, directory)
        channels = []
        with trace_path.open() as stream:
            for line in stream:
                event = json.loads(line)
                if event["event_type"] == "observation":
                    channels.extend(event["observation"]["channels"])
        hashes = [c["value"] for c in channels if c["name"] == "response_sha256"]
        if len(hashes) != 1:
            raise NativeExecutionError(f"native response digest absent or duplicated: {directory}")
        delivery = load_artifact(directory, hashes[0])
        verify_delivery_binding(delivery, request, world_config, seed)
        if replay:
            replay_receipt = self._follow(validation, "run", directory, "replay_receipt.json")
            self._follow(replay_receipt, "validate", directory, "replay_validation.json")
            replay_binding = verify_trace_replay(
                trace_path, self._trace_output(replay_receipt, directory), replay_receipt
            )
            immutable_json(directory / "replay_binding_verification.json", replay_binding)
        receipt = {
            "run_id": run_id,
            "runtime_version": "0.1.22",
            "upstream_commit": UPSTREAM_COMMIT,
            "directory": str(directory),
            "evidence_class": "simulator",
            "authority_anchor": validation.get("authority_anchor"),
            "embodied_evidence_bound": False,
            "physical_execution": False,
            "response_sha256": hashes[0],
            "trace_sha256": hashlib.sha256(trace_path.read_bytes()).hexdigest(),
            "replayed": replay,
        }
        immutable_json(directory / "native_receipt.json", receipt)
        self.last_receipt = receipt
        return delivery
